/**
 * App guide catalogue: where things are in the Paradigm app and how to use them.
 * Derived from the code: routes + route permissions from App.tsx (ProtectedRoute), menu paths from
 * components/navigation/DualTierSidebar.tsx (ENTERPRISE_PILLARS: pillar > folder > item), mobile nav from
 * components/layouts/BottomNav.tsx / MobileNavBar.tsx, button/tab labels from the page components.
 * `route` is the hash-router path (no '#'). `requiredPermission` is the ProtectedRoute permission (null = any signed-in user).
 */
export interface GuideEntry {
  id: string;
  title: string;
  route: string;
  /** Desktop sidebar path, e.g. ['Finance', 'Invoicing & Collections', 'Invoice Summary'] */
  menuPath: string[];
  steps: string[];
  requiredPermission?: string | null;
  /** Extra permission the sidebar item needs on top of the route one (when they differ). */
  menuPermission?: string | null;
  roles?: string[];
  keywords: string[];
  related?: string[];
  tips?: string[];
}

