export const GUIDE_BY_ID = new Map(GUIDE_CATALOGUE.map(g => [g.id, g]));

/** Generic words that must not match a page on their own. */
const STOP = new Set(['a', 'an', 'the', 'my', 'me', 'i', 'in', 'on', 'of', 'to', 'for', 'from', 'at', 'is', 'are', 'do', 'can', 'how', 'where', 'what', 'find', 'see', 'show', 'open', 'go', 'page', 'option', 'menu', 'section', 'screen', 'app', 'new', 'view', 'check', 'get', 'want', 'need', 'please', 'paradigm', 'there', 'it', 'and', 'or', 'with', 'by', 'this', 'that', 'be', 'make', 'use', 'using', 'we', 'you', 'doing', 'from']);
const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9& ]+/g, ' ').replace(/\s+/g, ' ').trim();
const stem = (w: string) => (w.length > 4 ? w.replace(/(ing|es|s|ed)$/, '') : w.replace(/s$/, ''));
const toks = (s: string) => norm(s).split(' ').filter(w => w && !STOP.has(w)).map(stem);

export interface GuideMatch { entry: GuideEntry; score: number }
/** Keyword matching (no AI): a whole keyword contained in the question beats token overlap. Sorted best first. */
export function matchGuides(topic: string): GuideMatch[] {
  const q = ' ' + norm(topic) + ' ';
  const qt = new Set(toks(topic));
  if (!qt.size) return [];
  const out: GuideMatch[] = [];
  for (const entry of GUIDE_CATALOGUE) {
    let best = 0;
    for (const kw of [entry.title, ...entry.keywords]) {
      const k = norm(kw);
      if (!k) continue;
      if (q.includes(' ' + k + ' ')) { best = Math.max(best, 10 + k.split(' ').length * 3 + k.length / 1000); continue; }
      const kt = toks(kw);
      if (!kt.length) continue;
      const hit = kt.filter(t => qt.has(t)).length;
      if (hit === kt.length && kt.length >= 2) best = Math.max(best, 6 + hit);
      else if (hit === kt.length && kt.length === 1 && k.length >= 4) best = Math.max(best, 4);
    }
    if (best) out.push({ entry, score: best });
  }
  return out.sort((a, b) => b.score - a.score);
}
